import pytest
from fastapi.testclient import TestClient
from app import app, _rate_store, RATE_LIMIT


@pytest.fixture(autouse=True)
def clear_rate_store():
    _rate_store.clear()
    yield
    _rate_store.clear()


client = TestClient(app)


def test_ping_works():
    r = client.get("/ping")
    assert r.status_code == 200


def test_items_works():
    r = client.get("/items")
    assert r.status_code == 200


def test_rate_limit_not_exceeded():
    for _ in range(RATE_LIMIT):
        r = client.get("/ping")
        assert r.status_code == 200


def test_rate_limit_exceeded_returns_429():
    for _ in range(RATE_LIMIT):
        client.get("/ping")
    r = client.get("/ping")  # one over the limit
    assert r.status_code == 429
    assert "rate limit" in r.json().get("detail", "").lower()


def test_different_ips_have_separate_counters():
    """Two different IPs should each get their own rate limit window."""
    # Exhaust limit for 127.0.0.1
    for _ in range(RATE_LIMIT):
        client.get("/ping", headers={"X-Forwarded-For": "10.0.0.1"})
    # 10.0.0.2 should still be under limit
    r = client.get("/ping", headers={"X-Forwarded-For": "10.0.0.2"})
    assert r.status_code == 200
